CREATE TABLE public.subscriptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,paddle_subscription_id text NOT NULL UNIQUE,paddle_customer_id text NOT NULL,product_id text NOT NULL,price_id text NOT NULL,status text NOT NULL,current_period_start timestamptz,current_period_end timestamptz,cancel_at_period_end boolean NOT NULL DEFAULT false,environment text NOT NULL CHECK(environment IN ('sandbox','live')),last_event_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.subscriptions TO authenticated; GRANT ALL ON public.subscriptions TO service_role; ALTER TABLE public.subscriptions ENABLE ROW LEVEL SECURITY; CREATE POLICY "Own subscriptions" ON public.subscriptions FOR SELECT TO authenticated USING(user_id=auth.uid()); CREATE POLICY "Admin subscriptions" ON public.subscriptions FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.payment_events(event_id text PRIMARY KEY,environment text NOT NULL,event_type text NOT NULL,occurred_at timestamptz NOT NULL,processed_at timestamptz NOT NULL DEFAULT now()); GRANT ALL ON public.payment_events TO service_role; ALTER TABLE public.payment_events ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.payment_history(id text PRIMARY KEY,user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,subscription_id text,status text NOT NULL,amount_minor bigint,currency text,environment text NOT NULL,occurred_at timestamptz NOT NULL); GRANT SELECT ON public.payment_history TO authenticated; GRANT ALL ON public.payment_history TO service_role; ALTER TABLE public.payment_history ENABLE ROW LEVEL SECURITY; CREATE POLICY "Own payments" ON public.payment_history FOR SELECT TO authenticated USING(user_id=auth.uid()); CREATE POLICY "Admin payments" ON public.payment_history FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.print_exports(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,format text NOT NULL CHECK(format IN ('pdf','png')),environment text NOT NULL CHECK(environment IN ('sandbox','live')),charged_free boolean NOT NULL,created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.print_exports TO authenticated; GRANT ALL ON public.print_exports TO service_role; ALTER TABLE public.print_exports ENABLE ROW LEVEL SECURITY; CREATE POLICY "Own print usage" ON public.print_exports FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.has_paid_access(_user_id uuid,_env text DEFAULT 'live') RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT (auth.uid()=_user_id OR auth.role()='service_role') AND (EXISTS(SELECT 1 FROM public.profiles WHERE id=_user_id AND plan='pro') OR EXISTS(SELECT 1 FROM public.subscriptions WHERE user_id=_user_id AND environment=_env AND product_id='studio_velas_access' AND status IN ('active','trialing','past_due','canceled') AND (current_period_end>now() OR (current_period_end IS NULL AND status IN ('active','trialing','past_due'))))) $$; REVOKE ALL ON FUNCTION public.has_paid_access(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.has_paid_access(uuid,text) TO authenticated,service_role;
CREATE FUNCTION public.authorize_print_export(_user_id uuid,_export_id uuid,_format text,_env text,_template_id uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE paid boolean; used integer; existing public.print_exports%ROWTYPE; BEGIN IF _env NOT IN ('sandbox','live') OR _format NOT IN ('pdf','png') THEN RAISE EXCEPTION 'invalid export'; END IF; PERFORM 1 FROM public.profiles WHERE id=_user_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'unknown user'; END IF; paid:=public.has_paid_access(_user_id,_env); SELECT * INTO existing FROM public.print_exports WHERE id=_export_id; SELECT count(*) INTO used FROM public.print_exports WHERE user_id=_user_id AND charged_free; IF existing.id IS NOT NULL THEN IF existing.user_id<>_user_id OR existing.format<>_format OR existing.environment<>_env THEN RAISE EXCEPTION 'invalid duplicate'; END IF; RETURN jsonb_build_object('ok',true,'remaining',greatest(0,7-used),'paid',paid); END IF; IF _template_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.templates WHERE id=_template_id AND is_premium) AND NOT paid THEN RETURN jsonb_build_object('ok',false,'reason','premium'); END IF; IF NOT paid AND used>=7 THEN RETURN jsonb_build_object('ok',false,'reason','limit','remaining',0); END IF; INSERT INTO public.print_exports VALUES(_export_id,_user_id,_format,_env,NOT paid,now()); RETURN jsonb_build_object('ok',true,'remaining',greatest(0,7-used-CASE WHEN paid THEN 0 ELSE 1 END),'paid',paid); END $$; REVOKE ALL ON FUNCTION public.authorize_print_export(uuid,uuid,text,text,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.authorize_print_export(uuid,uuid,text,text,uuid) TO service_role;